        const r = svg("rect", { x: labelW, y: y + 6, width: w, height: 18, rx: 6, class: `rc-bar rc-s${i === 0 ? 0 : 1}` });
        const tt = svg("title"); tt.textContent = `${lab}: ${money(v)}`; r.append(tt);
