  // ---------- exports ----------
  function reportText(r) {
    const lines = [r.title, r.period, "", r.summary];
    (r.kpis || []).forEach(k => lines.push(`• ${k.label}: ${k.value}${k.note ? ` (${k.note})` : ""}`));
    (r.sections || []).forEach(sec => {
      lines.push("", sec.heading.toLocaleUpperCase("tr-TR"));
      if (sec.text) lines.push(sec.text);
      (sec.bullets || []).forEach(b => lines.push(`- ${b}`));
      if (sec.table?.columns?.length) { lines.push(sec.table.columns.join(" | ")); sec.table.rows.forEach(row => lines.push(row.join(" | "))); }
    });
    lines.push("", "Akış Bütçe · Bütçe AI");
    return lines.filter((l, i, a) => !(l === "" && a[i - 1] === "")).join("\n");
  }
