    if (photoOwner !== uid) { clearPhotos(); photoOwner = uid; }
    if (!uid) { setStatus("Fotoğraf eklemek için giriş yapmalısın."); return; }
    const images = incoming.filter(f => f && f.type.startsWith("image/"));
    if (!images.length) return;
    if (photos.length + images.length > 4 || images.some(f => f.size > 10 * 1024 * 1024)) { setStatus("En fazla 4 fotoğraf; her biri en fazla 10 MB olabilir."); return; }
    photos.push(...images); tray.hidden = false; filePicker.value = "";
